import{_ as a,o as s,c as t,a2 as o}from"./chunks/framework.BM5YPQmL.js";const u=JSON.parse('{"title":"The 8 merged apps: wizard, direct, classic","description":"","frontmatter":{},"headers":[],"relativePath":"manual/mega-apps.md","filePath":"manual/mega-apps.md"}'),i={name:"manual/mega-apps.md"};function n(d,e,c,r,l,p){return s(),t("div",null,[...e[0]||(e[0]=[o(`<h1 id="the-8-merged-apps-wizard-direct-classic" tabindex="-1">The 8 merged apps: wizard, direct, classic <a class="header-anchor" href="#the-8-merged-apps-wizard-direct-classic" aria-label="Permalink to &quot;The 8 merged apps: wizard, direct, classic&quot;">​</a></h1><p>Since 3.0.0 the user surface is organized around eight merged apps. Each of them opens the same three doors; which one you use depends on whether you are exploring (wizard), scripting (classic), or want to be explicit about bypassing the menus (direct).</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>ush&gt; disk-tool                wizard: menus, checks, confirmations</span></span>
<span class="line"><span>ush&gt; disk-tool direct lsblk   explicit verbatim passthrough</span></span>
<span class="line"><span>ush&gt; disk-tool lsblk          classic dispatch = the historical command</span></span></code></pre></div><p>All three produce the <strong>same service output</strong> - the wizard only adds detection, safety confirmations and grouping around it.</p><h2 id="the-wizard-no-arguments" tabindex="-1">The wizard (no arguments) <a class="header-anchor" href="#the-wizard-no-arguments" aria-label="Permalink to &quot;The wizard (no arguments)&quot;">​</a></h2><p>Running the app with no arguments opens an intent wizard:</p><ul><li>Numbered menus: press a single digit key (<code>1</code>-<code>9</code>) to pick, <code>q</code> or ESC to quit/back. No Enter needed.</li><li>Destructive paths (mkfs, abdisk, install, rm, power actions) ask for the target name, make you <strong>retype it</strong>, then a bare <code>y</code> - anything else aborts.</li><li>Wizards read the same English service output lines a script would and can <strong>cross domains</strong>: the <code>update</code> wizard fixes a missing IP through DHCP and a missing A/B disk through <code>lsblk</code> + <code>abdisk</code> before it ever checks for updates.</li><li>Everything renders through the active language: <code>lang zh</code> switches the whole wizard, menus included.</li></ul><h2 id="direct-explicit-passthrough" tabindex="-1">direct (explicit passthrough) <a class="header-anchor" href="#direct-explicit-passthrough" aria-label="Permalink to &quot;direct (explicit passthrough)&quot;">​</a></h2><p><code>&lt;app&gt; direct &lt;op&gt; [args...]</code> runs one op exactly as the historical command did, with the word <code>direct</code> stripped from the argument line. Use it in scripts when you want the intent to be self-documenting:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>ush&gt; update direct           the historical bare \`update\` (online flow)</span></span>
<span class="line"><span>ush&gt; sound-tool direct volume 50</span></span>
<span class="line"><span>ush&gt; sysdiag direct health watch</span></span></code></pre></div><h2 id="classic-verbatim-dispatch" tabindex="-1">classic (verbatim dispatch) <a class="header-anchor" href="#classic-verbatim-dispatch" aria-label="Permalink to &quot;classic (verbatim dispatch)&quot;">​</a></h2><p><code>&lt;app&gt; &lt;op&gt; [args...]</code> looks the op up in the app&#39;s table and runs it with the historical spelling - output is byte-identical to running the single-command app of the same name. The single-command apps remain registered (the interface-freeze rule: commands are added, never removed), so <code>lsblk</code> and <code>disk-tool lsblk</code> are two doors into the same service call.</p><p>An unknown op name prints the app&#39;s usage with its full op table:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>ush&gt; disk-tool nope</span></span>
<span class="line"><span>disk-tool: unknown op: nope</span></span>
<span class="line"><span>usage: disk-tool            (interactive menu)</span></span>
<span class="line"><span>       disk-tool direct &lt;op&gt; [args]   (explicit passthrough)</span></span>
<span class="line"><span>       disk-tool &lt;op&gt; [args]          (classic op dispatch)</span></span>
<span class="line"><span>ops:</span></span>
<span class="line"><span>  ahci</span></span>
<span class="line"><span>  nvme</span></span>
<span class="line"><span>  ...</span></span></code></pre></div><h2 id="app-by-app" tabindex="-1">App-by-app <a class="header-anchor" href="#app-by-app" aria-label="Permalink to &quot;App-by-app&quot;">​</a></h2><h3 id="update-the-ota-wizard" tabindex="-1">update - the OTA wizard <a class="header-anchor" href="#update-the-ota-wizard" aria-label="Permalink to &quot;update - the OTA wizard&quot;">​</a></h3><p><code>update</code> (no args) walks the whole update intent in five steps:</p><ol><li><strong>Network</strong> - reads the IP status; a 0.0.0.0 address offers a DHCP fix, then rechecks.</li><li><strong>A/B disk</strong> - reads <code>update status</code>; when the A/B disk is absent it lists <code>lsblk</code>, asks for the device name (retyped + confirmed) and runs <code>abdisk</code>, then rechecks until present.</li><li><strong>DNS</strong> - parses the live <code>config get update_url</code> value and resolves the update host.</li><li><strong>Check</strong> - <code>checkupdate</code>: up-to-date ends the wizard with OK.</li><li><strong>Install</strong> - confirmed online update, then a confirmed reboot into the new slot.</li></ol><p>Classic surface: <code>update status</code>, <code>update --local &lt;path&gt;</code>, <code>update &lt;anything&gt;</code> = the verbatim OTA op.</p><h3 id="disk-tool-disks-and-filesystems" tabindex="-1">disk-tool - disks and filesystems <a class="header-anchor" href="#disk-tool-disks-and-filesystems" aria-label="Permalink to &quot;disk-tool - disks and filesystems&quot;">​</a></h3><p>Menu: lsblk / parted / mkfs submenu (FAT32, exFAT, ext4 - double confirmation) / mount manager (list, mount, umount, fatmount, fatstat) / fsck / dskstat / A/B manager (status, create, abcfg).</p><p>Classic table: all 23 block ops (<code>ahci</code> .. <code>abcfg</code>) plus the 6 fs ops (<code>mount</code>, <code>mounts</code>, <code>umount</code>, <code>fatmount</code>, <code>fatstat</code>, <code>tree</code>).</p><h3 id="net-tool-connectivity" tabindex="-1">net-tool - connectivity <a class="header-anchor" href="#net-tool-connectivity" aria-label="Permalink to &quot;net-tool - connectivity&quot;">​</a></h3><p>Menu: show IP / DHCP / static IP (address, mask, gateway collected one field at a time) / DNS / WiFi manager (status, scan, test, sdio) / Bluetooth (status, usb, uart, test) / firewall / route + arp / connectivity tests (ping, wget, ssh, dnstest - ping and wget go through the same NETCMD bridge the historical apps used).</p><p>Classic table: the 14 net ops (<code>arp</code> .. <code>sshd</code>) plus <code>wifi</code> and <code>bt</code>.</p><h3 id="sound-tool-audio" tabindex="-1">sound-tool - audio <a class="header-anchor" href="#sound-tool-audio" aria-label="Permalink to &quot;sound-tool - audio&quot;">​</a></h3><p>Menu: device overview / volume (digits-only validation) / the 440 Hz test tone / per-driver status (HDA, AC&#39;97, SB16, ES1370, virtio-snd, USB audio) / selftests (the RW loopback, sample-rate accuracy, or every driver&#39;s own selftest in sequence).</p><p>Classic table: all 17 snd ops (<code>sound</code> .. <code>sample_rate_test</code>).</p><h3 id="files-the-file-manager" tabindex="-1">files - the file manager <a class="header-anchor" href="#files-the-file-manager" aria-label="Permalink to &quot;files - the file manager&quot;">​</a></h3><p>Menu: ls / tree / disk usage (df + du) / copy / move / delete (with confirmation) / edit (the full-screen editor) / info + permissions (stat, then optional chmod with octal validation).</p><p>Dispatch here is fork + execve of the historical programs (the <code>run</code> mechanism), because the file tools are real programs, not service calls - the editor is interactive. Classic table: <code>ls</code>, <code>tree</code>, <code>df</code>, <code>du</code>, <code>cp</code>, <code>mv</code>, <code>rm</code>, <code>edit</code>, <code>stat</code>, <code>chmod</code>.</p><h3 id="sysdiag-system-diagnostics" tabindex="-1">sysdiag - system diagnostics <a class="header-anchor" href="#sysdiag-system-diagnostics" aria-label="Permalink to &quot;sysdiag - system diagnostics&quot;">​</a></h3><p>Menu: health snapshot / kernel log / memory picture (mem + frag + heap) / scheduler + sync stats / crash records / log tools (logcat, logctl, health export, health watch) / selftest lab (memtest, heaptest, fstest, vmtest - individually or all four in sequence).</p><p>Classic table: all 39 diag ops plus health, dmesg/logcat/logctl and watchdog - 46 entries. <code>crashtest</code> (deliberate panic injection) is reachable through classic/direct only, on purpose.</p><h3 id="hwinfo-hardware-inventory" tabindex="-1">hwinfo - hardware inventory <a class="header-anchor" href="#hwinfo-hardware-inventory" aria-label="Permalink to &quot;hwinfo - hardware inventory&quot;">​</a></h3><p>Menu: system summary (uname -a + memory) / clock sources (RTC, HPET, PM timer, TSC) / PCI (lspci, pcidump, pcibars, pcie) / ACPI / SMBus-I2C / USB / camera &amp; legacy input / display + font + encoding.</p><p>Classic table: 26 read-only ops across the display, time, net, diag, usb, camera and input surfaces.</p><h3 id="power-power-management" tabindex="-1">power - power management <a class="header-anchor" href="#power-power-management" aria-label="Permalink to &quot;power - power management&quot;">​</a></h3><p>Menu: shutdown / reboot / halt (each behind a bare-y confirmation) / sleep N seconds (digits validated) / power-path selftests (each with its own warning + confirmation - the probes exercise the real power paths).</p><p>Classic table: <code>shutdown</code>, <code>poweroff</code>, <code>reboot</code>, <code>halt</code>, <code>sleep</code>, <code>poweroff_test</code>, <code>suspend_test</code>, <code>halt_test</code>, <code>reboot_test</code>.</p><h2 id="i18n" tabindex="-1">i18n <a class="header-anchor" href="#i18n" aria-label="Permalink to &quot;i18n&quot;">​</a></h2><p>Every wizard line renders through the active locale. Switch with:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>ush&gt; lang zh        (menus, prompts and verdicts become Chinese)</span></span>
<span class="line"><span>ush&gt; lang en        (back to English)</span></span></code></pre></div><p>A missing translation falls back to English, then to the key itself - an untranslated app can never crash or print garbage.</p>`,44)])])}const g=a(i,[["render",n]]);export{u as __pageData,g as default};
